<?php
declare(strict_types=1);
function scaled(string $value,int $precision=2): int { $value=trim($value); if(!preg_match('/^\d{1,8}(?:\.\d{1,'.$precision.'})?$/D',$value)) throw new DomainException('Enter a positive amount with at most '.$precision.' decimal places (maximum 99,999,999).'); [$a,$b]=array_pad(explode('.',$value),2,''); return (int)$a*(10**$precision)+(int)str_pad($b,$precision,'0'); }
function decimal(int $minor,int $precision=2): string { $scale=10**$precision; return intdiv($minor,$scale).'.'.str_pad((string)($minor%$scale),$precision,'0',STR_PAD_LEFT); }
function round_div(int $value,int $divisor): int { return intdiv($value+intdiv($divisor,2),$divisor); }
function calculate_items(array $input): array {
    if(count($input)<1||count($input)>100) throw new DomainException('Add between 1 and 100 line items.');
    $totals=['subtotal'=>0,'discount_total'=>0,'tax_total'=>0,'total'=>0]; $items=[];
    foreach($input as $item) {
        $description=trim((string)($item['description']??'')); if($description===''||mb_strlen($description)>500) throw new DomainException('Each item needs a description.');
        $q=scaled((string)($item['quantity']??''),3); $rate=scaled((string)($item['rate']??'')); $discount=scaled((string)($item['discount_rate']??'0')); $tax=scaled((string)($item['tax_rate']??'0'));
        if($q<1||$q>10000000||$rate>100000000||$discount>10000||$tax>10000) throw new DomainException('Item quantity, price, discount, or tax is outside the supported range.');
        $sub=round_div($q*$rate,1000); $disc=round_div($sub*$discount,10000); $taxAmount=round_div(($sub-$disc)*$tax,10000); $total=$sub-$disc+$taxAmount;
        $row=['product_id'=>empty($item['product_id'])?null:(int)$item['product_id'],'description'=>$description,'quantity'=>decimal($q,3),'rate'=>decimal($rate),'discount_rate'=>decimal($discount),'tax_rate'=>decimal($tax),'subtotal'=>decimal($sub),'discount_total'=>decimal($disc),'tax_total'=>decimal($taxAmount),'total'=>decimal($total)]; $items[]=$row;
        foreach(['subtotal'=>$sub,'discount_total'=>$disc,'tax_total'=>$taxAmount,'total'=>$total] as $k=>$v) $totals[$k]+=$v;
    }
    if($totals['total']>9999999999) throw new DomainException('Document total exceeds the supported amount.');
    return ['items'=>$items,'totals'=>array_map(fn($v)=>decimal($v),$totals)];
}
function document_status(array $doc): string { if($doc['type']==='quotation') return $doc['status']; if(in_array($doc['status'],['Draft','Void'],true)) return $doc['status']; $paid=scaled((string)($doc['paid']??'0')); if($paid>=scaled((string)$doc['total'])) return 'Paid'; if($paid>0) return 'Partially Paid'; return $doc['due_date']<date('Y-m-d')?'Overdue':'Issued'; }
function document_record(int $id,bool $lock=false): array { $doc=one('SELECT d.*,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.document_id=d.id AND p.business_id=d.business_id AND p.reversed_at IS NULL) paid,c.name customer_name,c.email customer_email,c.address customer_address,c.gstin customer_gstin FROM documents d JOIN customers c ON c.id=d.customer_id AND c.business_id=d.business_id WHERE d.id=? AND d.business_id=?'.($lock?' FOR UPDATE':''),[$id,bid()]); if(!$doc) throw new DomainException('Document not found.'); return $doc; }
function create_document(string $type,array $data,array $input): int {
    require_permission($type==='invoice'?'invoices.create':'quotations.create');
    $customer=one("SELECT * FROM customers WHERE id=? AND business_id=? AND status='Active'",[(int)$data['customer_id'],bid()]); if(!$customer) throw new DomainException('Choose an active customer.');
    $issue=valid_date((string)$data['issue_date']); $due=valid_date((string)$data['due_date']); if($due<$issue) throw new DomainException('Due date must be on or after the document date.');
    $calc=calculate_items($input); foreach($calc['items'] as $item) if($item['product_id']&&!one("SELECT id FROM products WHERE id=? AND business_id=? AND status='Active'",[$item['product_id'],bid()])) throw new DomainException('Choose an active product.');
    return transaction(function() use($type,$data,$issue,$due,$calc) {
        query('SELECT id FROM businesses WHERE id=? FOR UPDATE',[bid()]);
        $seq=(int)setting($type.'_sequence',1000)+1; save_setting($type.'_sequence',$seq); $number=($type==='invoice'?'INV':'QUO').'-'.str_pad((string)$seq,4,'0',STR_PAD_LEFT);
        query('INSERT INTO documents(business_id,customer_id,type,number,issue_date,due_date,subtotal,discount_total,tax_total,total,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[bid(),$data['customer_id'],$type,$number,$issue,$due,$calc['totals']['subtotal'],$calc['totals']['discount_total'],$calc['totals']['tax_total'],$calc['totals']['total'],mb_substr((string)($data['notes']??''),0,4000)]); $id=(int)db()->lastInsertId();
        foreach($calc['items'] as $i) query('INSERT INTO document_items(document_id,product_id,description,quantity,rate,discount_rate,tax_rate,subtotal,discount_total,tax_total,total) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$id,...array_values($i)]);
        audit($type.'.draft_created','document',$id); return $id;
    });
}
function issue_document(int $id): void { transaction(function() use($id){ $d=document_record($id,true); require_permission($d['type']==='invoice'?'invoices.issue':'quotations.issue'); if($d['status']!=='Draft') throw new DomainException('Only a draft can be issued.'); $c=one('SELECT * FROM customers WHERE id=? AND business_id=?',[$d['customer_id'],bid()]); $snapshot=['business'=>profile()+['name'=>business()['name']],'customer'=>array_intersect_key($c,array_flip(['name','company','email','phone','address','gstin']))]; query('UPDATE documents SET status=?,snapshot=?,version=version+1 WHERE id=? AND business_id=?',[$d['type']==='invoice'?'Issued':'Sent',json_encode($snapshot,JSON_THROW_ON_ERROR),$id,bid()]); audit('document.issued','document',$id); }); }
function record_payment(int $id,string $amount,string $date,string $method,string $reference,string $key): int { require_permission('payments.record'); $minor=scaled($amount); if($minor<=0) throw new DomainException('Payment must be greater than zero.'); valid_date($date); if(!in_array($method,['Cash','Bank transfer','UPI','Card','Cheque','Other'],true)||!preg_match('/^[a-f0-9]{64}$/D',$key)) throw new DomainException('Invalid payment method or submission key.'); return transaction(function() use($id,$minor,$date,$method,$reference,$key){ $d=document_record($id,true); if($d['type']!=='invoice'||$d['status']!=='Issued') throw new DomainException('Payments can only be recorded against issued invoices.'); $existing=one('SELECT id,document_id,amount,payment_date,method,reference FROM payments WHERE business_id=? AND idempotency_key=?',[bid(),$key]); if($existing) { if((int)$existing['document_id']!==$id||scaled($existing['amount'])!==$minor||$existing['payment_date']!==$date||$existing['method']!==$method||$existing['reference']!==mb_substr($reference,0,160)) throw new DomainException('This submission key has already been used.'); return (int)$existing['id']; } if($minor>scaled($d['total'])-scaled($d['paid'])) throw new DomainException('Payment cannot exceed the outstanding balance.'); query('INSERT INTO payments(business_id,document_id,customer_id,payment_date,amount,method,reference,notes,idempotency_key) VALUES(?,?,?,?,?,?,?,?,?)',[bid(),$id,$d['customer_id'],$date,decimal($minor),$method,mb_substr($reference,0,160),'',$key]); $payment=(int)db()->lastInsertId(); audit('payment.recorded','payment',$payment,['amount'=>decimal($minor),'invoice'=>$id]); return $payment; }); }
function create_document_nested(array $old,array $items): int { $id=create_document('invoice',['customer_id'=>$old['customer_id'],'issue_date'=>date('Y-m-d'),'due_date'=>date('Y-m-d',strtotime('+30 days')),'notes'=>$old['notes']],$items); query('UPDATE documents SET source_id=? WHERE id=? AND business_id=?',[$old['id'],$id,bid()]);audit('quotation.converted','document',(int)$old['id'],['invoice_id'=>$id]);return $id; }
